<template>
  <div class="chat-container">
    <!-- 聊天头部：标题 + 操作按钮 -->
    <div class="chat-header">
      <h2>🤖 Agent AI 助手对话</h2>
      <div class="header-actions">
        <el-button @click="openInputDialog" type="primary" icon="el-icon-edit" size="small">
          输入配置
        </el-button>
        <el-button @click="clearChat" type="danger" icon="el-icon-delete" size="small" style="margin-left: 10px;">
          清空对话
        </el-button>
      </div>
    </div>

    <!-- 聊天记录显示区域：增加滚动容器高度和样式 -->
    <div class="chat-history-container">
      <div class="chat-history" ref="chatHistory">
        <!-- 消息列表 -->
        <div
          v-for="(message, index) in messages"
          :key="index"
          :class="['message', message.type]"
        >
          <div class="avatar" :class="message.type">
            {{ message.type === 'ai' ? '🤖' : '👤' }}
          </div>
          <div class="message-content">
            <div class="sender">{{ message.sender }}</div>
            <div class="content" v-html="renderMarkdown(message.content)"></div>
            <!-- AI回复专属：复制按钮 -->
            <el-button 
              v-if="message.type === 'ai'" 
              type="text" 
              icon="el-icon-document-copy" 
              size="mini" 
              @click="copyContent(message.content)"
              class="copy-btn"
            >
              复制
            </el-button>
          </div>
        </div>
      
        <div v-if="loading" class="message ai">
          <div class="avatar ai">🤖</div>
          <div class="message-content">
            <div class="sender">AI 小助手</div>
            <div class="content typing-indicator">
              <span></span>
              <span></span>
              <span></span>
            </div>
          </div>
        </div>
      </div>
    </div>

    <!-- 输入配置弹窗 -->
    <el-dialog
      title="接口配置表单"
      :visible.sync="dialogVisible"
      width="60%"
      center
    >
      <el-form :model="form" label-width="120px" class="ai-form">
        <el-form-item label="🔧 业务类型:">
          <el-select
            v-model="form.bizType"
            placeholder="请选择业务类型"
            style="width: 100%"
          >
            <el-option value="CREATE_ARCHIVE" label="建档"></el-option>
            <el-option value="SYNC_APPLY" label="申请单发送"></el-option>
            <el-option value="DELETE_APPLY" label="申请单取消"></el-option>
            <el-option value="SYNC_CHAG" label="账单发送"></el-option>
          </el-select>
        </el-form-item>

        <el-form-item label="📥 请求格式化:">
          <el-input
            v-model="form.requestFormatter"
            type="textarea"
            :rows="8"
            placeholder="请输入接口请求入参,可以为json/xml"
            style="font-family: 'Monaco', 'Menlo', 'Ubuntu Mono', monospace;"
          ></el-input>
        </el-form-item>

        <el-form-item label="📤 响应格式化:">
          <el-input
            v-model="form.responseFormatter"
            type="textarea"
            :rows="8"
            placeholder="请输入接口响应出参,可以为json/xml"
            style="font-family: 'Monaco', 'Menlo', 'Ubuntu Mono', monospace;"
          ></el-input>
        </el-form-item>
      </el-form>
      <template #footer>
        <div class="dialog-footer">
          <el-button @click="dialogVisible = false">取消</el-button>
          <el-button 
            type="primary" 
            @click="sendForm" 
            :loading="dialogLoading"
          >
            {{ dialogLoading ? '发送中...' : '发送配置' }}
          </el-button>
        </div>
      </template>
    </el-dialog>
  </div>
</template>

<script>
import { marked } from 'marked';
// 引入真实接口（请确保路径正确）
import { sendChatMessage } from '@/api/aiChat.js';

export default {
  name: 'AiChat',
  data() {
    return {
      // 聊天消息列表
      messages: [
        {
          type: 'ai',
          sender: 'AI 助手',
          content: '您好！我是您的接口AI小助手，请告诉我您配置的接口类型和参数，并给出相应的格式化数据。'
        }
      ],
      // 表单数据（弹窗专用）
      form: {
        bizType: 'CREATE_ARCHIVE',
        requestFormatter: '',
        responseFormatter: ''
      },
      // 加载状态
      loading: false,        // 对话区域加载状态
      dialogVisible: false,  // 弹窗显隐
      dialogLoading: false   // 弹窗发送加载状态
    };
  },
  methods: {
    // 打开输入配置弹窗
    openInputDialog() {
      this.dialogVisible = true;
    },
    async sendForm() {
      if (!this.form.requestFormatter.trim() && !this.form.responseFormatter.trim()) {
        this.$message({
          message: '请至少填写请求或响应格式化数据',
          type: 'warning'
        });
        return;
      }

      this.dialogVisible = false;
      this.loading = true;

      const userContent = `业务类型: ${this.form.bizType}\n请求格式: \`\`\`json\n${this.form.requestFormatter || '无'}\n\`\`\`\n响应格式: \`\`\`json\n${this.form.responseFormatter || '无'}\n\`\`\``;
      this.messages.push({
        type: 'user',
        sender: '您',
        content: userContent
      });

      this.$nextTick(() => {
        this.scrollToBottom();
      });

      try {
        const result = await sendChatMessage(this.form);
        
        if (typeof result !== 'string' || result.trim() === '') {
          throw new Error('AI 返回内容为空或格式错误');
        }

        this.messages.push({
          type: 'ai',
          sender: 'AI 助手',
          content: result
        });
      } catch (error) {
        console.error('发送失败:', error);
        this.messages.push({
          type: 'ai',
          sender: 'AI 助手',
          content: '抱歉，接口请求失败，请检查网络或配置后重试。'
        });
        this.$message.error('请求失败：' + (error.message || '未知错误'));
      } finally {
        this.loading = false; // ✅ 确保 always 关闭 loading
        this.$nextTick(() => {
          this.scrollToBottom();
        });
      }
    },
    // 清空聊天记录
    clearChat() {
      this.messages = [
        {
          type: 'ai',
          sender: 'AI 助手',
          content: '您好！我是您的接口AI小助手，请告诉我您配置的接口类型和参数，并给出相应的格式化数据。'
        }
      ];
      this.$message.success('聊天记录已清空');
      this.$nextTick(() => {
        this.scrollToBottom();
      });
    },
    // 滚动到底部
    scrollToBottom() {
      const container = this.$refs.chatHistory;
      if (container) {
        container.scrollTop = container.scrollHeight;
      }
    },
    // 渲染Markdown内容
    renderMarkdown(content) {
      if (!content) return '';
      return marked.parse(content, {
        gfm: true,
        breaks: true,
        sanitize: false,
        headerIds: false,
        highlight: function (code, lang) {
          return `<pre class="code-block ${lang}"><code>${code}</code></pre>`;
        }
      });
    },
    // 兼容式复制内容：适配Windows/Mac所有主流浏览器
    copyContent(content) {
      // 方案1：使用剪贴板API（现代浏览器推荐）
      if (navigator.clipboard && window.isSecureContext) {
        navigator.clipboard.writeText(content)
          .then(() => {
            this.$message.success('内容已复制到剪贴板 ✅');
          })
          .catch(err => {
            // API失败时降级到方案2
            this.fallbackCopyTextToClipboard(content);
          });
      } else {
        // 方案2：创建临时文本域复制（兼容旧浏览器/非安全上下文）
        this.fallbackCopyTextToClipboard(content);
      }
    },
    // 降级复制方案：临时文本域
    fallbackCopyTextToClipboard(content) {
      // 创建隐藏的文本域
      const textArea = document.createElement('textarea');
      textArea.value = content;
      // 定位到视口外，避免闪烁
      textArea.style.position = 'fixed';
      textArea.style.top = '-999px';
      textArea.style.left = '-999px';
      textArea.style.width = '2em';
      textArea.style.height = '2em';
      // 避免iOS中键盘自动弹出
      textArea.style.opacity = '0';

      document.body.appendChild(textArea);
      textArea.focus();
      textArea.select(); // 选中内容

      try {
        // 执行复制命令（兼容IE11+、所有现代浏览器）
        const successful = document.execCommand('copy');
        if (successful) {
          this.$message.success('内容已复制到剪贴板 ✅');
        } else {
          this.$message.error('复制失败，请手动复制');
        }
      } catch (err) {
        this.$message.error('复制失败：' + err.message);
      } finally {
        // 移除临时文本域
        document.body.removeChild(textArea);
      }
    }
  },
  mounted() {
    this.scrollToBottom();
  }
};
</script>

